        db.SavedChanges += AssignEventId;
        void AssignEventId(object? sender, SavedChangesEventArgs args)
        {
            db.SavedChanges -= AssignEventId;
        }
        PendingTicketTypeOwners.Add((newEvent, ticketTypes));
    }

