        try
        {
            snapshot = await gateway.CreateSessionAsync(request, cancellationToken);
        }
        catch (CheckoutConfigurationException exception)
        {
            // The request never reached Stripe, so no session exists; clear the attempt marker.
            order.CheckoutAttemptStartedUtc = null;
            order.PlannedSessionExpiresUtc = null;
