const slot = (id, d, h) => ({ id, startUtc: day(d, h), endUtc: day(d, h + 2), isBookable: true });
const events = [
  { id: 1, name: 'Harvest Lantern Walk', description: 'Lantern stroll.', venue: 'Orchard Trail', registrationType: 'GeneralAdmission', imagePath: '/images/lantern-walk.svg', fromPriceCents: 1200, timeSlots: [slot(1, 0, 17), slot(2, 0, 19)] },
  { id: 2, name: 'Pumpkin Patch Hayride', description: 'Hayride.', venue: 'Farm', registrationType: 'GeneralAdmission', imagePath: '/images/hayride.svg', fromPriceCents: 1000, timeSlots: [slot(3, 2, 10), slot(4, 2, 13)] },
  { id: 3, name: 'Orchard Cider Tasting', description: 'Cider.', venue: 'Barn', registrationType: 'GeneralAdmission', imagePath: '/images/cider.svg', fromPriceCents: 3000, timeSlots: [slot(5, 5, 14), slot(6, 5, 18)] },
  { id: 4, name: 'Winter Market & Skating', description: 'Market.', venue: 'Green', registrationType: 'GeneralAdmission', imagePath: '/images/market.svg', fromPriceCents: 1200, timeSlots: [slot(7, 9, 11), slot(8, 9, 15)] },
  { id: 5, name: 'Snowlight Forest Trail', description: 'Trail.', venue: 'Woods', registrationType: 'GeneralAdmission', imagePath: '/images/forest-trail.svg', fromPriceCents: 2600, timeSlots: [slot(9, 12, 17), slot(10, 12, 19)] },
  { id: 6, name: 'Winter Lights Concert', description: 'Concert.', venue: 'Evergreen Hall', registrationType: 'ReservedSeating', imagePath: '/images/concert.svg', fromPriceCents: 8500, timeSlots: [slot(11, 14, 15), slot(12, 14, 19)] },
];
let theme = 'Fall';
const sections = [['ORCHESTRA-LEFT', 'Orchestra Left', 8500, 60, 200], ['VIP-CENTER', 'VIP Center', 12500, 240, 120], ['ORCHESTRA-RIGHT', 'Orchestra Right', 8500, 420, 200]]
  .map(([code, name, priceCents, ox, oy], si) => ({ id: si + 1, code, name, priceCents, seats: ['A', 'B'].flatMap((row, ri) => [1, 2, 3].map((n) => ({ id: si * 6 + ri * 3 + n, label: `${code}-${row}-0${n}`, row, seatNumber: n, svgX: ox + 30 + (n - 1) * 40, svgY: oy + 30 + ri * 44, active: true }))) }));
const json = (res, code, body) => { res.writeHead(code, { 'Content-Type': 'application/json' }); res.end(JSON.stringify(body)); };
http.createServer((req, res) => {
  const url = new URL(req.url, 'http://x');
  const m = url.pathname.match(/^\/api\/events\/(\d+)(.*)$/);
  if (url.pathname === '/api/events') return json(res, 200, events);
  if (url.pathname === '/api/settings/theme') {
    if (req.method === 'PUT') { let b = ''; req.on('data', (c) => (b += c)); req.on('end', () => { theme = JSON.parse(b).activeTheme; json(res, 200, { activeTheme: theme }); }); return; }
    return json(res, 200, { activeTheme: theme });
  }
  if (m && m[2] === '/availability') return json(res, 200, { eventId: +m[1], timeSlotId: +url.searchParams.get('timeSlotId'), currency: 'usd', isBookable: true, ticketTypes: [{ ticketTypeId: 1, name: 'Adult', description: 'Ages 13+', priceCents: 2400, capacity: 20, remaining: 17 }, { ticketTypeId: 2, name: 'Child', description: 'Ages 3-12', priceCents: 1200, capacity: 15, remaining: 2 }] });
  if (m && m[2] === '/seating') return json(res, 200, { eventId: 6, currency: 'usd', sections });
  if (m && m[2] === '/seating/availability') return json(res, 200, { eventId: 6, timeSlotId: 11, isBookable: true, seats: sections.flatMap((s) => s.seats).map((s) => ({ seatId: s.id, status: s.id === 8 ? 'sold' : s.id === 9 ? 'held' : 'available' })), sections: sections.map((s) => ({ sectionId: s.id, remaining: s.id === 2 ? 4 : 6, total: 6 })) });
  json(res, 404, { error: { code: 'not_found', message: 'nope' } });
}).listen(5050, '127.0.0.1');
EOF
