const { chromium } = require('playwright');
const { execSync, spawn } = require('child_process');
const A = process.argv[2], S = process.argv[3];
const api = (path, opts = {}) => fetch('http://127.0.0.1:5050' + path, { headers: { 'Content-Type': 'application/json', ...(opts.headers || {}) }, ...opts }).then(r => r.json());
const startApi = () => { spawn('dotnet', [`${A}/bin/Debug/net10.0/EventRegistration.Api.dll`, '--contentRoot', A], { env: { ...process.env, ASPNETCORE_URLS: 'http://127.0.0.1:5050' }, detached: true, stdio: 'ignore' }).unref(); };
const sleep = ms => new Promise(r => setTimeout(r, ms));
(async () => {
  const events = await api('/api/events');
  const ev = events[0];
  const avail = await api(`/api/events/${ev.id}/availability?timeSlotId=${ev.timeSlots[0].id}`);
  const mk = (key) => api('/api/orders', { method: 'POST', headers: { 'Idempotency-Key': key }, body: JSON.stringify({ timeSlotId: ev.timeSlots[0].id, tickets: [{ ticketTypeId: avail.ticketTypes[0].ticketTypeId, quantity: 2 }] }) });
  const order = await mk('ui-check-1');
  console.log('created order', order.status, order.totalCents);

  const browser = await chromium.launch();
  const page = await browser.newPage({ viewport: { width: 1100, height: 900 } });
  // 1. Failed first verification (API down) -> retry after API is back.
  execSync(`pkill -f "EventRegistration.Api.dll" || true`); await sleep(1000);
  await page.goto(`http://127.0.0.1:5173/?orderId=${order.id}&checkout=success`);
  await page.getByRole('heading', { name: 'We could not verify your order yet' }).waitFor();
  console.log('1a failed verification shows retry:', await page.getByRole('button', { name: 'Try again' }).isVisible(), 'url:', new URL(page.url()).search);
  startApi(); for (let i = 0; i < 30; i++) { try { await api('/api/health'); break; } catch { await sleep(500); } }
  await page.getByRole('button', { name: 'Try again' }).click();
  await page.getByText(order.id).waitFor();
  console.log('1b after retry heading:', await page.locator('h2').first().innerText());
  // 2. Refresh keeps the same order.
  await page.reload();
  await page.getByText(order.id).waitFor();
  console.log('2 after refresh heading:', await page.locator('h2').first().innerText(), 'url:', new URL(page.url()).search);
  await page.screenshot({ path: `${S}/real-refresh.png` });
  // 3. Cancel return then refresh: released once, refresh shows same released order.
  const order2 = await mk('ui-check-2');
  await page.goto(`http://127.0.0.1:5173/?orderId=${order2.id}&checkout=cancel`);
  await page.getByText(order2.id).waitFor();
  console.log('3a cancel heading:', await page.locator('h2').first().innerText(), 'url:', new URL(page.url()).search);
  await page.reload(); await page.getByText(order2.id).waitFor();
  console.log('3b refresh after cancel:', await page.locator('h2').first().innerText());
  // 4. Book another event clears the reference.
  await page.getByRole('button', { name: 'Book another event' }).click();
  console.log('4 url after reset:', JSON.stringify(new URL(page.url()).search));
  // 5. Real booking flow up to Stripe hand-off (no Stripe key/network here).
  await page.getByRole('button', { name: new RegExp(`${ev.name} on`) }).click();
  await page.getByRole('button', { name: /^More / }).first().click();
  console.log('5a remaining text:', await page.locator('.remaining').first().innerText());
  await page.getByRole('button', { name: 'Review order' }).click();
  await page.getByRole('button', { name: 'Pay with Stripe' }).click();
  await page.locator('.error').waitFor();
  console.log('5b pay result:', await page.locator('.error').innerText());
  await browser.close();
})().catch(e => { console.error('ERR', e.message); process.exit(1); });
EOF
