S=/tmp/claude-0/-home-claude/dadc0381-3554-5b4b-a537-d3fd6c9ebe70/scratchpad; A=$S/realapi; cd $A && timeout 300 dotnet build -nologo 2>&1 | grep -E " error |Build succeeded"; rm -f blevinspass.db*; (ASPNETCORE_ENVIRONMENT=Development ASPNETCORE_URLS=http://127.0.0.1:5050 nohup dotnet bin/Debug/net10.0/EventRegistration.Api.dll --contentRoot $A > api.log 2>&1 &); cd /home/claude/bp/client && (nohup npx vite > $S/vite4.log 2>&1 &); sleep 6
cat > $S/reset-ui2.cjs <<'EOF'
const { chromium } = require('playwright');
const { execFileSync } = require('child_process');
const A = process.argv[2], S = process.argv[3];
const db = (sql) => execFileSync('python3', ['-c', `import sqlite3;c=sqlite3.connect('${A}/blevinspass.db');r=c.execute("""${sql}""").fetchall();c.commit();print(r)`]).toString().trim();
const api = (p, o = {}) => fetch('http://127.0.0.1:5050' + p, { ...o, headers: { 'Content-Type': 'application/json', ...(o.headers || {}) } }).then(r => r.json());
(async () => {
  console.log('direct POST without origin/header:', await fetch('http://127.0.0.1:5050/api/dev/demo-reset', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: '{"confirm":true}' }).then(r => r.status));
  const browser = await chromium.launch();
  const page = await browser.newPage({ viewport: { width: 1280, height: 900 } });
  await page.goto('http://127.0.0.1:5173/');
  // Blocked case: a paid order this workspace cannot refund (no Stripe here).
  const ev = (await api('/api/events'))[0];
  const avail = await api(`/api/events/${ev.id}/availability?timeSlotId=${ev.timeSlots[0].id}`);
  const t = avail.ticketTypes[0];
  const order = await api('/api/orders', { method: 'POST', headers: { 'Idempotency-Key': 'ui2-paid' }, body: JSON.stringify({ timeSlotId: ev.timeSlots[0].id, tickets: [{ ticketTypeId: t.ticketTypeId, quantity: 2 }] }) });
  db(`update Orders set Status='Confirmed', StripeSessionId='cs_test_workspace_fake2' where lower(Id)='${order.id}'`);
  await page.locator('.demo-reset').scrollIntoViewIfNeeded();
  await page.getByRole('button', { name: 'Reset demo availability' }).click();
  await page.getByRole('button', { name: 'Reset and refund' }).click();
  await page.locator('.demo-reset-status.failed').waitFor();
  console.log('blocked message:', await page.locator('.demo-reset-status').innerText());
  console.log('per-order details:', await page.locator('.demo-reset-details').innerText());
  db(`update Orders set Status='Released' where lower(Id)='${order.id}'`);
  await page.getByRole('button', { name: 'Reset demo availability' }).click();
  await page.getByRole('button', { name: 'Reset and refund' }).click();
  await page.locator('.demo-reset-status:not(.failed)').filter({ hasText: 'restored' }).waitFor();
  console.log('via proxy success:', await page.locator('.demo-reset-status').innerText(), '| inventory:', db('select sum(Reserved),sum(Sold) from SlotInventories'));
  await page.locator('.site-footer').screenshot({ path: `${S}/reset-footer-final.png` });
  await browser.close();
})().catch(e => { console.error('ERR', e.message); process.exit(1); });
EOF
(nohup node $S/reset-ui2.cjs $A $S > $S/reset-ui2.log 2>&1 &); for i in $(seq 1 40); do grep -qE "via proxy|ERR" $S/reset-ui2.log && break; sleep 1; done; cat $S/reset-ui2.log; python3 $S/stop_helpers.py

